{
  "propositions": [
    {
      "id": "P1",
      "proposition": "When an order of protection issued pursuant to Title 36, Chapter 3, Part 6 protects a Tennessee public-school student from another student enrolled in the same school, the principal must remove the respondent student from any classroom or school-sponsored event or activity shared with the petitioner student.",
      "importance": "core",
      "section": "SECTION 1(a)",
      "source_quote": "shall remove the student who is named as the respondent in the\n\n order of protection from any classroom or school-sponsored event or activity shared with\n\n the student who is named as the petitioner in the order of protection."
    },
    {
      "id": "P2",
      "proposition": "The school or school district must provide the respondent student with alternative instruction for any class or course from which the student is removed under this section.",
      "importance": "core",
      "section": "SECTION 1(b)",
      "source_quote": "The school or school district shall provide the student who is named as the\n\n respondent in the order of protection with alternative instruction for any class or course\n\n from which the student is removed for purposes of this section."
    },
    {
      "id": "P3",
      "proposition": "The required removal from a classroom or school-sponsored event or activity lasts only for the period during which the order of protection is in effect.",
      "importance": "supporting",
      "section": "SECTION 1(b)",
      "source_quote": "This section only\n\n requires a student's removal from a classroom or school-sponsored event or activity for\n\n the period of time for which an order of protection is in effect."
    },
    {
      "id": "P4",
      "proposition": "The act takes effect upon becoming law and applies to orders of protection entered on or after that date.",
      "importance": "supporting",
      "section": "SECTION 2",
      "source_quote": "This act takes effect upon becoming a law, the public welfare requiring it,\n\nand applies to orders of protection entered on or after such date."
    }
  ]
}
